// Prepara um item pequeno para a fila Redis.
// A chave prioriza atendimento_id; se nao existir, usa o wa_id.
const entrada = $('When Executed by Another Workflow').first().json;
const config = $('Variaveis buffer').first().json;
const evento = entrada.evento ?? entrada.payload ?? entrada;
const atendimentoId = String(evento.atendimento_id ?? '').trim();
const waId = String(evento.wa_id ?? '').trim();
const mensagemId = String(evento.mensagem_id ?? '').trim();
const chaveBase = atendimentoId ? 'atendimento:' + atendimentoId : 'wa:' + waId;
const redisKey = String(config.redis_key_prefixo_buffer ?? '') + chaveBase;

if (!waId) throw new Error('WA_ID_AUSENTE_PARA_BUFFER');
if (!mensagemId) throw new Error('MENSAGEM_ID_AUSENTE_PARA_BUFFER');

const item = {
  id: mensagemId,
  recebido_em: evento.recebido_em ?? new Date().toISOString(),
  texto: String(evento.texto ?? '').trim(),
  evento,
};

return [{ json: {
  redis_key: redisKey,
  mensagem_id: mensagemId,
  buffer_item_json: JSON.stringify(item),
  evento
} }];

// So a execucao da ultima mensagem pode seguir.
// Execucoes antigas encerram sem chamar o orquestrador.
const atual = $('Preparar item do buffer').first().json;
const busca = $('Buscar mensagens do buffer').first().json;
const bruto = busca.mensagens_buffer ?? [];
const lista = Array.isArray(bruto) ? bruto : [bruto].filter(Boolean);
const mensagens = lista.map((valor) => {
  try { return typeof valor === 'string' ? JSON.parse(valor) : valor; }
  catch { return null; }
}).filter(Boolean);

const ultima = mensagens[mensagens.length - 1] ?? null;
const souUltimaMensagem = Boolean(ultima && String(ultima.id) === String(atual.mensagem_id));

return [{ json: {
  processar: souUltimaMensagem,
  motivo: souUltimaMensagem ? 'ULTIMA_MENSAGEM_DA_JANELA' : 'EXECUCAO_SUPERADA_POR_MENSAGEM_MAIS_NOVA',
  redis_key: String(atual.redis_key ?? ''),
  mensagem_id: String(atual.mensagem_id ?? ''),
  mensagens_json: JSON.stringify(mensagens)
} }];

// Junta os textos da janela e preserva o evento mais recente como base.
const avaliacao = $('Avaliar ultima mensagem').first().json;
const config = $('Variaveis buffer').first().json;
let mensagens = [];
try { mensagens = JSON.parse(avaliacao.mensagens_json || '[]'); } catch { mensagens = []; }

const separador = String(config.separador_mensagens ?? '\n');
const textos = mensagens
  .map((mensagem) => String(mensagem.texto ?? mensagem.evento?.texto ?? '').trim())
  .filter(Boolean);
const ultimo = mensagens[mensagens.length - 1] ?? {};
const payload = {
  ...(ultimo.evento ?? {}),
  texto: textos.join(separador).trim(),
  buffer_mensagens: {
    aplicado: true,
    quantidade: mensagens.length,
    mensagem_ids: mensagens.map((mensagem) => String(mensagem.id ?? '')).filter(Boolean),
    redis_key: String(avaliacao.redis_key ?? '')
  }
};

return [{ json: {
  processar: true,
  codigo: 'BUFFER_MENSAGENS_AGREGADO',
  payload,
  quantidade_mensagens: mensagens.length
} }];
